"""Point-in-time Longbridge forward-adjusted WEEKLY US ETF closes (public reference snapshot).

The stored weekly date represents the Monday when a week begins; the close
is only observable after the last US trading day that week (after China Friday).
Data through Friday 2026-11-20. Stored compactly for reproducible offline runs.
Precision: rounded to USD 0.01. No intrawweek execution can be inferred.
"""
import base64
import pandas as pd

_DATA = {
'QQQ': '',
'SPY': '',
'RSP': '',
'SMH': '',
'BIL': '',
}

def _decode(encoded:str)->list[float]:
    b=base64.b64decode(encoded); values=[]; p=0; x=0; shift=0
    for byte in b:
        x|=(byte & 0x7f)<<shift
        if byte & 0x80:
            shift+=7; continue
        p+= (-(x//2+1) if x&1 else x//2)
        values.append(round(p/100,2))
        x=0;shift=0
    if shift:raise ValueError('truncated snapshot')
    return values

def load_us_prices() -> pd.DataFrame:
    dates=pd.date_range('2020-11-23','2026-11-16',freq='W-MON',name='week_start')
    data={k:_decode(v) for k,v in _DATA.items()}
    if any(len(v)!=len(dates) for v in data.values()):
        raise ValueError('US market snapshot length mismatch')
    frame=pd.DataFrame(data,index=dates)
    if frame.isna().any().any() or frame.le(0).any().any():raise ValueError('invalid market snapshot')
    assert abs(frame.QQQ.iloc[-1]-608.45)<.001 and abs(frame.BIL.iloc[-1]-91.59)<.001
    return frame

_US_OPEN = {
'QQQ':'',
'BIL':'',
}

def load_us_open()->pd.DataFrame:
    dates=pd.date_range('2020-11-23','2026-11-16',freq='W-MON',name='week_start')
    opens=pd.DataFrame({k:_decode(v) for k,v in _US_OPEN.items()},index=dates)
    if opens.shape!=(313,2):raise ValueError('US open prices missing')
    assert abs(opens.QQQ.iloc[-1]-671.04)<.001 and abs(opens.BIL.iloc[-1]-91.54)<.001
    return opens
